import{_ as n,c as i,o as r,ae as t}from"./chunks/framework.CHDT0Kbg.js";const f=JSON.parse('{"title":"Persim kennenlernen","description":"","frontmatter":{},"headers":[],"relativePath":"de/guide/introduction.md","filePath":"de/guide/introduction.md","lastUpdated":1795170900000}'),a={name:"de/guide/introduction.md"};function s(l,e,d,o,u,h){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="persim-kennenlernen" tabindex="-1">Persim kennenlernen <a class="header-anchor" href="#persim-kennenlernen" aria-label="Permalink to &quot;Persim kennenlernen&quot;">​</a></h1><p>Ein Mac-Browser, der sofort loslegt: Tabs, Suche, Lesezeichen und Downloads.</p><h2 id="von-anfang-an" tabindex="-1">Von Anfang an <a class="header-anchor" href="#von-anfang-an" aria-label="Permalink to &quot;Von Anfang an&quot;">​</a></h2><ul><li><strong>Surfen und Suchen.</strong> URL oder Frage in die Adressleiste tippen. Oft besuchte Seiten erscheinen zuerst.</li><li><strong>Tabs und Fenster.</strong> Öffnen, ziehen, gruppieren, stummschalten, in der Vorschau ansehen. Mit ⌘⇧A findest du einen Tab schnell wieder.</li><li><strong>Wiederfinden.</strong> Lesezeichen, Lesezeichenleiste, Verlauf, Downloads und „Letzte Sitzung wiederherstellen“.</li></ul><h2 id="etwas-ruhiger" tabindex="-1">Etwas ruhiger <a class="header-anchor" href="#etwas-ruhiger" aria-label="Permalink to &quot;Etwas ruhiger&quot;">​</a></h2><ul><li>Werbeblocker mit Abonnements, eigenen Regeln und Erlaubnisliste für vertraute Seiten.</li><li>Dunkle Seiten, stumme Tabs und Pop-up-Blocker in den Einstellungen.</li><li>Ein privates Fenster (⌘⇧N) schreibt keinen Verlauf.</li></ul><h2 id="videos-und-lange-texte" tabindex="-1">Videos und lange Texte <a class="header-anchor" href="#videos-und-lange-texte" aria-label="Permalink to &quot;Videos und lange Texte&quot;">​</a></h2><ul><li>Das Medienfenster listet Videos auf der Seite. Gespeicherte Videos werden zu einer MP4 und lassen sich mit jeder App öffnen.</li><li>Der Lesemodus (⌘⇧R) lässt nur den Artikel übrig. Screenshots und komplette Seiten als PDF sind ebenfalls möglich.</li></ul><h2 id="passend-fur-dich" tabindex="-1">Passend für dich <a class="header-anchor" href="#passend-fur-dich" aria-label="Permalink to &quot;Passend für dich&quot;">​</a></h2><p>Hell, dunkel oder Systemeinstellung; sechs Akzentfarben; drei Lesezeichenleisten-Modi; 25 Oberflächensprachen. Design ändert sich sofort, eine Sprachänderung nach dem erneuten Öffnen des Fensters.</p>',10)])])}const g=n(a,[["render",s]]);export{f as __pageData,g as default};
